-- Northwind-style seed data for DBcraWler.
-- Deterministic sample dataset. Loaded by Postgres init container.
BEGIN;

-- Read-only application user (ADR: defense in depth with app-level guardrails)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='app_readonly') THEN
    CREATE ROLE app_readonly LOGIN PASSWORD 'readonly_password';
  END IF;
END $$;

CREATE TABLE categories (
    category_id   INTEGER PRIMARY KEY,
    category_name TEXT NOT NULL,
    description   TEXT
);

CREATE TABLE suppliers (
    supplier_id   INTEGER PRIMARY KEY,
    company_name  TEXT NOT NULL,
    city          TEXT,
    country       TEXT,
    phone         TEXT
);

CREATE TABLE products (
    product_id   INTEGER PRIMARY KEY,
    product_name TEXT NOT NULL,
    supplier_id  INTEGER REFERENCES suppliers(supplier_id),
    category_id  INTEGER REFERENCES categories(category_id),
    unit_price   NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
    units_in_stock INTEGER NOT NULL DEFAULT 0 CHECK (units_in_stock >= 0),
    discontinued INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE employees (
    employee_id INTEGER PRIMARY KEY,
    first_name  TEXT NOT NULL,
    last_name   TEXT NOT NULL,
    title       TEXT,
    hire_date   DATE NOT NULL,
    city        TEXT,
    country     TEXT,
    reports_to  INTEGER REFERENCES employees(employee_id)
);

CREATE TABLE customers (
    customer_id  TEXT PRIMARY KEY,
    company_name TEXT NOT NULL,
    contact_name TEXT,
    city         TEXT,
    country      TEXT,
    segment      TEXT NOT NULL,
    joined_at    DATE NOT NULL
);

CREATE TABLE shippers (
    shipper_id   INTEGER PRIMARY KEY,
    company_name TEXT NOT NULL,
    phone        TEXT
);

CREATE TABLE orders (
    order_id     INTEGER,
    customer_id  TEXT REFERENCES customers(customer_id),
    employee_id  INTEGER REFERENCES employees(employee_id),
    shipper_id   INTEGER REFERENCES shippers(shipper_id),
    order_date   DATE NOT NULL,
    required_date DATE NOT NULL,
    shipped_date DATE,
    freight      NUMERIC(10,2) NOT NULL DEFAULT 0,
    ship_city    TEXT,
    ship_country TEXT,
    order_status TEXT NOT NULL DEFAULT 'pending',
    PRIMARY KEY (order_id, order_date)
);

CREATE TABLE order_details (
    order_id      INTEGER,
    order_date    DATE,
    product_id    INTEGER REFERENCES products(product_id),
    quantity      INTEGER NOT NULL CHECK (quantity > 0),
    unit_price    NUMERIC(10,2) NOT NULL CHECK (unit_price >= 0),
    discount      NUMERIC(3,2) NOT NULL DEFAULT 0 CHECK (discount >= 0 AND discount <= 1),
    PRIMARY KEY (order_id, product_id, order_date),
    FOREIGN KEY (order_id, order_date) REFERENCES orders(order_id, order_date)
);








GRANT USAGE ON SCHEMA public TO app_readonly;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO app_readonly;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO app_readonly;
COMMIT;

